#!/usr/bin/env python
"""The paper's numbers.tex and Table IV from the all-events models (A = reports/m3_1A_all, B = reports/m3_1A_all_no2p2h)
evaluated on CC nu_mu events: the technote numbers of the CC nu_mu subset evaluation and the holdout (scripts/technote_numbers.py),
the seven-variable closure by subset (scripts/paper_closure_macros.py), the marginal-pull summaries of the calibration on the
CC nu_mu control (bayes_uncertainty_{A,B}_ccctl.json, same recipe as scripts/paper_fig_pulls.py), and the 2p2h reachability
macros (scripts/paper_fig_coverage.py). Writes PaperDraft/numbers.tex and PaperDraft/tables/holdout_summary.tex.
Usage: scripts/paper_macros_all.py [--paper PaperDraft]"""
import argparse, json, pathlib, re, subprocess, sys
import numpy as np
ap = argparse.ArgumentParser(); ap.add_argument("--paper", default="PaperDraft"); ap.add_argument("--eval", default="reports/m3_1A_all_ccnumu"); ap.add_argument("--holdout", default="reports/holdout_2p2h_1A_all"); ap.add_argument("--cal", default="reports/bayes_1A_all"); a = ap.parse_args()
P = pathlib.Path(a.paper); tmp = pathlib.Path("reports/all_events/paper_numbers.tex")
subprocess.run([sys.executable, "scripts/technote_numbers.py", a.eval, str(tmp), "--m1", "none", "--holdout", a.holdout], check=True, capture_output=True)
subprocess.run([sys.executable, "scripts/paper_closure_macros.py"], check=True, capture_output=True)
parts = ["% Generated by scripts/paper_macros_all.py: all-events models evaluated on CC nu_mu events (technote numbers, closure by subset, pull subsets, 2p2h reachability).\n",
         tmp.read_text(), pathlib.Path("reports/all_events/closure_macros.tex").read_text(), pathlib.Path("reports/coverage_2p2h/macros.tex").read_text(), pathlib.Path("reports/ensemble/macros.tex").read_text(), pathlib.Path("reports/ensemble/pull_macros.tex").read_text()]
# marginal pulls of the four non-calorimetry observables with the surrogate's own uncertainty (as the pull figures), A and B, control and held-out 2p2h
KEYS = ("marg_recoil", "marg_muP", "marg_dthx", "marg_nprong"); ci = ["% marginal pulls on the CC nu_mu control and the held-out 2p2h events (calibration with the CC nu_mu control subset)\n"]
for m in "AB":
    f = pathlib.Path(a.cal) / f"bayes_uncertainty_{m}_ccctl.json"
    if not f.exists(): print(f"warning: {f} missing, \\nCI{m}... macros not written"); continue
    S = json.load(open(f))["binned"]
    for split, tag in (("control", "Ctl"), ("heldout", "OOD")):
        p = np.concatenate([np.array(S[split][k]["pull"], float) for k in KEYS]); p = p[np.isfinite(p)]
        ci.append(f"\\newcommand{{\\nCI{m}Marg{tag}RMS}}{{{np.sqrt(np.mean(p ** 2)):.2f}}}\n\\newcommand{{\\nCI{m}Marg{tag}Within}}{{{100 * np.mean(np.abs(p) < 2):.0f}\\%}}\n\\newcommand{{\\nCI{m}Marg{tag}Bins}}{{{len(p)}}}\n")
H = json.load(open(pathlib.Path(a.holdout) / "summary.json")); N = int(re.search(r"data: (\d+) events", open("reports/logs_all/m3_A.log").read()).group(1))  # the population (all events in the training volume)
ci.append(f"\\newcommand{{\\nHfracTwoPpop}}{{{100 * H['coverage']['n_2p2h'] / N:.1f}\\%}}\n")
parts.append("".join(ci)); (P / "numbers.tex").write_text("\n".join(parts))
# Table IV: seven-variable closure by column from the macros, prong closure row from the holdout table
ht = (pathlib.Path(a.holdout) / "tables" / "holdout_summary.tex").read_text(); prong = next(l for l in ht.splitlines() if l.startswith("prong closure AUC"))
cols = [("ATwoP", "full model, 2p2h"), ("BTwoP", "2p2h holdout, 2p2h"), ("BCtl", "2p2h holdout, control"), ("All", "full model, full test")]
rows = ["\\begin{tabular}{lcccc}", "\\toprule", " & " + " & ".join(c[1] for c in cols) + " \\\\", "\\midrule",
        "closure AUC, reconstructed only & " + " & ".join(f"\\nAEClo{c[0]}CIMarg{{}}" for c in cols) + " \\\\",
        "closure AUC, with truth features & " + " & ".join(f"\\nAEClo{c[0]}CICond{{}}" for c in cols) + " \\\\",
        "with truth: muon / vertex / recoil & " + " & ".join(f"\\nAEClo{c[0]}MuCond{{}} / \\nAEClo{c[0]}VtxCond{{}} / \\nAEClo{c[0]}RecoilCond{{}}" for c in cols) + " \\\\",
        prong, "\\bottomrule", "\\end{tabular}"]
(P / "tables" / "holdout_summary.tex").write_text("\n".join(rows) + "\n"); print("written", P / "numbers.tex", P / "tables" / "holdout_summary.tex")
